// RegisterEntryRetrievalObserver binds dependency construction to a database module. Its factory runs once per nonempty complete fetch/batch and selected model role; write hydration, DTOs and scalar reads skip it.
func RegisterEntryRetrievalObserver(registrar *foundation.Registrar, pool foundation.Key[*database.DB], observer EntryRetrievalObserver, construct func(foundation.Resolver) (func() EntryRetrievalHooks, error)) error {
	return database.RegisterObserver(registrar, pool, observer, construct)
}
func (EntryRetrievalHooks) foundryRetrievalHooks(ctx context.Context, observerSet lifecycle.Observers) (foundryquery.RetrievalHooks[Entry], error) {
	factories, err := lifecycle.RetrievalObserverFactories[Entry, EntryRetrievalHooks](observerSet)
	if err != nil {
		return foundryquery.RetrievalHooks[Entry]{}, err
	}
	var allHooks []EntryRetrievalHooks
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Entry]{}, err
	}
	for _, factory := range factories {
		if err := ctx.Err(); err != nil {
			return foundryquery.RetrievalHooks[Entry]{}, err
		}
		allHooks = append(allHooks, factory())
	}
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Entry]{}, err
	}
	return foundryquery.RetrievalHooks[Entry]{Retrieved: func(ctx context.Context, executor database.Executor, item Entry) error {
		for _, hooks := range allHooks {
			if err := ctx.Err(); err != nil {
				return err
			}
			if hooks.Retrieved != nil {
				if err := hooks.Retrieved(ctx, executor, item); err != nil {
					return err
				}
			}
		}
		return ctx.Err()
	}}, nil
}

